True def transform(grid):
    out = [row[:] for row in grid]
    baseline = next((r for r, row in enumerate(grid) if any(row)), None)
    if baseline is None:
        return out
    heights = {2: 4, 8: 3}
    for c, color in enumerate(grid[baseline]):
        if color in heights:
            for d in range(1, heights[color] + 1):
                r = baseline - d
                if r >= 0:
                    out[r][c] = color if d == heights[color] else 1
    return out
